def natural_sort_strings(strings):
    def _tokenize(s):
        tokens = []
        i = 0
        while i < len(s):
            if s[i].isdigit():
                j = i
                while j < len(s) and s[j].isdigit():
                    j += 1
                tokens.append(('digit', int(s[i:j])))
                i = j
            else:
                j = i
                while j < len(s) and not s[j].isdigit():
                    j += 1
                tokens.append(('text', s[i:j]))
                i = j
        return tokens

    def _key(s):
        tokens = _tokenize(s)
        kind_flags = [t[0] for t in tokens]
        has_text = any(k == 'text' for k in kind_flags)
        has_digit = any(k == 'digit' for k in kind_flags)
        if has_text and not has_digit:
            kind_priority = 0
        elif has_digit and not has_text:
            kind_priority = 1
        else:
            kind_priority = 2
        type_tags = []
        for t in tokens:
            if t[0] == 'text':
                type_tags.append((0, t[1]))
            else:
                type_tags.append((1, t[1]))
        return (kind_priority, type_tags)

    return sorted(strings, key=_key)

import functools

def natural_sort_strings(strings):
    if not strings:
        return []

    def _key(s):
        parts = []
        i = 0
        n = len(s)
        while i < n:
            if s[i].isdigit():
                j = i
                while j < n and s[j].isdigit():
                    j += 1
                parts.append(('d', int(s[i:j])))
                i = j
            else:
                j = i
                while j < n and not s[j].isdigit():
                    j += 1
                parts.append(('t', s[i:j]))
                i = j
        return parts

    @functools.cmp_to_key
    def _compare(a, b):
        ka = _key(a)
        kb = _key(b)
        for pa, pb in zip(ka, kb):
            if pa[0] != pb[0]:
                return -1 if pa[0] == 'd' else 1
            if pa[1] != pb[1]:
                return (pa[1] > pb[1]) - (pa[1] < pb[1])
        if len(ka) != len(kb):
            return -1 if len(ka) < len(kb) else 1
        return 0

    return sorted(strings, key=_key)
